/** Normalisasi untuk pencocokan nama. */
function normName(s) {
  return String(s || '')
    .toLowerCase()
    .replace(/[™®’]/g, "'")
    .replace(/[^a-z0-9'&: .+-]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

/** Cari entri game dari nama bebas yang diketik user. */
function findGame(input) {
  const q = normName(input);
  if (!q) return null;
  // 1) cocok persis dengan salah satu alias
  for (const g of GAMES) {
    if (g.alias.some((a) => normName(a) === q)) return g;
  }
  // 2) nama resmi cocok persis
  for (const g of GAMES) {
    if (normName(g.name) === q) return g;
  }
  // 3) skor: berapa banyak kata yang cocok + alias terpanjang yang termuat.
  //    Contoh: "the last of us 2" harus kena versi Part II Remastered,
  //    bukan Part I (kata-katanya lebih cocok).
  const bersih = (t) => t.replace(/^[^a-z0-9]+|[^a-z0-9]+$/g, '');
  const qt = q.split(' ').map(bersih).filter(Boolean);
  let best = null;
  let bestKey = null;
  for (const g of GAMES) {
    const hay = new Set();
    for (const a of [g.name, ...g.alias]) {
      for (const t of normName(a).split(' ')) {
        const bt = bersih(t);
        if (bt) hay.add(bt);
      }
    }
    let hit = 0;
    for (const t of qt) if (hay.has(t)) hit += 1;
    const cover = qt.length ? hit / qt.length : 0;
    let longest = 0;
    for (const a of g.alias) {
      const na = normName(a);
      if (!na) continue;
      if (q.includes(na) || na.includes(q)) longest = Math.max(longest, na.length);
    }
    // ambang batas: jangan asal cocok. Harus mirip betulan.
    //  - alias/nama yang termuat harus cukup panjang (min. ~separuh panjang input), ATAU
    //  - mayoritas kata input ada di nama/alias (>= 60%)
    const minLongest = Math.max(3, Math.min(6, Math.ceil(q.length * 0.5)));
    if (longest < minLongest && cover < 0.6) continue;
    if (!bestKey || cover > bestKey[0] || (cover === bestKey[0] && longest > bestKey[1])) {
      best = g;
      bestKey = [cover, longest];
    }
  }
  return best;
}

/**
 * Cari ID aplikasi Discord untuk sebuah nama game (kalau ada).
 * @param {string} gameName nama yang diketik user
 * @param {string} [explicit] PS5_APP_ID manual (menang kalau diisi)
 */
function findAppId(gameName, explicit) {
  const given = String(explicit || '').trim();
  if (/^[0-9]{5,25}$/.test(given)) return given;
  const g = findGame(gameName);
  return g ? g.id : '';
}

/** Nama resmi versi Discord (mis. "Marvel's Spider-Man Remastered"). */
function officialName(gameName) {
  const g = findGame(gameName);
  return g ? g.name : '';
}

/** info lengkap: { id, name, alias } atau null */
function findGameInfo(gameName, explicit) {
  const given = String(explicit || '').trim();
  const g = findGame(gameName);
  if (g) return { ...g, id: /^[0-9]{5,25}$/.test(given) ? given : g.id };
  return null;
}

/** Ubah nilai platform jadi nilai resmi Discord. */
function normalizePlatform(value, fallback = 'ps5') {
  const raw = String(value || '').trim().toLowerCase();
  if (!raw) return fallback;
  if (PLATFORM_ALIAS[raw]) return PLATFORM_ALIAS[raw];
  if (PLATFORMS.includes(raw)) return raw;
  return fallback;
}

/** Label manusiawi: "PS5", "PS4", "Xbox", "Desktop". */
function platformLabel(platform) {
  return { ps5: 'PS5', ps4: 'PS4', xbox: 'Xbox', desktop: 'PC', ios: 'iPhone/iPad', android: 'Android', meta_quest: 'Meta Quest', samsung: 'Samsung' }[platform] || platform;
}

class Ps5Presence extends EventEmitter {
  /**
   * @param {{logger:any, cfg:any}} opts  cfg = config.ps5
   */
  constructor({ logger, cfg }) {
    super();
    this.log = logger;
    this.cfg = cfg;

    this.platform = normalizePlatform(cfg.platform, 'ps5');
    this.details = String(cfg.details || '').trim();
    this.timer = cfg.timer !== false;
    this.startedAt = Date.now();
    this.sessionId = crypto.randomBytes(16).toString('hex');
    this.gameId = crypto.randomBytes(8).toString('hex');
    this.resolve(cfg.game, false);
  }

  /**
   * Tentukan nama + ID aplikasi dari nama game yang ditulis.
   * @param {string} game   nama game (bebas, tidak peka huruf besar/kecil)
   * @param {boolean} resetTimer  true = sesi baru (timer mulai dari 0 lagi)
   */
  resolve(game, resetTimer = false) {
    const typed = String(game || '').trim() || 'Fortnite';
    const info = findGameInfo(typed, this.cfg.appId);
    // default: pakai nama RESMI Discord (tampilannya sama seperti orang main betulan).
    // Kalau mau tetap pakai nama yang kamu tulis, set PS5_OFFICIAL_NAME=false.
    this.name = info && this.cfg.officialName !== false ? info.name : typed;
    this.matchedGame = info ? info.name : '';
    this.appId = info ? info.id : findAppId(typed, this.cfg.appId);
    if (resetTimer) this.startedAt = Date.now();
    return { name: this.name, id: this.appId, matched: Boolean(info) };
  }

  /**
   * Dipakai dashboard: ganti game saat script sedang jalan (tanpa restart).
   * @returns {{ok:boolean, name:string, id:string|null, matched:boolean}}
   */
  applyGame(game) {
    const res = this.resolve(game, true);
    if (res.matched) {
      this.log.info(`PS5: ganti game -> "${res.name}" (ikon resmi OK)`);
    } else {
      this.log.warn(`PS5: ganti game -> "${res.name}" (belum terdaftar, tanpa ikon)`);
    }
    this.emit('change');
    return res;
  }

  /**
   * Dipakai dashboard: ganti platform (ps5 / ps4 / desktop / xbox ...) saat jalan.
   * Perlu untuk quest Discord yang jalurnya "desktop", mis. quest EA SPORTS FC 27.
   */
  setPlatform(value) {
    const baru = normalizePlatform(value, this.platform);
    if (baru === this.platform) return this.platform;
    const lama = this.platform;
    this.platform = baru;
    this.log.info(`PS5: platform diubah ${lama} -> ${baru} (dari dashboard).`);
    this.emit('change');
    return this.platform;
  }

  /** Dipakai dashboard: nyala/matikan mode PS5 saat script jalan. */
  setEnabled(on) {
    const next = Boolean(on);
    if (this.cfg.enabled === next) return this.cfg.enabled;
    this.cfg.enabled = next;
    if (next) this.startedAt = Date.now();
    this.log.info(next ? 'PS5: mode pura-pura DINYALAKAN dari dashboard.' : 'PS5: mode pura-pura DIMATIKAN dari dashboard.');
    this.emit('change');
    return this.cfg.enabled;
  }

  get enabled() {
    return Boolean(this.cfg.enabled);
  }

  /** Label untuk log, mis. "Fortnite (platform ps5)". */
  get summary() {
    return `${this.name} (platform ${this.platform}${this.appId ? ', ikon game asli' : ', tanpa ikon'})`;
  }

  /** Aktivitas untuk gateway Discord (null = tidak ada). */
  activity() {
    if (!this.enabled) return null;
    const act = {
      id: this.gameId,
      session_id: this.sessionId,
      name: this.name,
      type: 0, // Playing
      platform: this.platform, // <- INI kuncinya: bikin Discord menampilkan sebagai konsol
      created_at: this.startedAt,
      official_game_id: null,
    };
    if (this.timer) act.timestamps = { start: this.startedAt };
    if (this.appId) act.application_id = this.appId; // ikon/art game asli
    if (this.details) act.details = this.details;
    return act;
  }

  /** Nyalakan (kalau enabled). Dipanggil sekali oleh index.js. */
  async start() {
    if (!this.enabled) return;
    this.startedAt = Date.now();
    this.resolve(this.cfg.game, false);
    this.log.info(
      `PS5: mode "pura-pura" ON — tampil sebagai "Playing ${this.name}" di platform ${platformLabel(this.platform)}` +
        (this.timer ? ' (timer jalan)' : ''),
    );
    if (!this.appId) {
      this.log.warn(`PS5: tidak ada ID aplikasi untuk "${this.name}" — ikon game tidak akan muncul. Isi PS5_APP_ID kalau perlu.`);
    }
    this.emit('change');
  }

  stop() {
    // tidak ada timer/polling: aktivitasnya statis
  }
}

module.exports = {
  Ps5Presence,
  findAppId,
  findGame,
  findGameInfo,
  officialName,
  normalizePlatform,
  platformLabel,
  PLATFORMS,
  GAMES,
};
